    # ---- eight players (2026-11-13): the capacity of the tables, the ceiling of each title (four unless its row says more: Mario Kart 7's five), the one place where 0 is four,
    #      the five places where the lobby applies it, the real Download Play that stays at four, the two hubs that take the row's ceiling to the lobby, and the tests that hold it ----
    ('eight: a title that says nothing has eight players (Kirby receives 8)', 'Includes/azl/dlp_types.hpp', 'constexpr u32 kTitlePlayers = 4;', 'constexpr u32 kTitlePlayers = 8;'),
    ('eight: a configuration of 0 means the capacity of the tables', 'Includes/azl/dlp_types.hpp', 'return said == 0 ? kTitlePlayers : (said < 2', 'return said == 0 ? kMaxPlayers : (said < 2'),
    ('eight: what a configuration says is taken as it is', 'Includes/azl/dlp_types.hpp', '    return said == 0 ? kTitlePlayers : (said < 2 ? 2 : (said > kMaxPlayers ? kMaxPlayers : said));', '    return said;'),
    ('eight: a ceiling above the tables is not cut', 'Includes/azl/dlp_types.hpp', '(said < 2 ? 2 : (said > kMaxPlayers ? kMaxPlayers : said));', '(said < 2 ? 2 : said);'),
    ('eight: the assertion that 0 is four is gone', 'Includes/azl/dlp_types.hpp', 'static_assert(TitlePlayers(0) == 4, "a configuration that says nothing is a title of four players");\n', ''),
    ('eight: the assertion that the default ceiling fits the tables is gone', 'Includes/azl/dlp_types.hpp', 'static_assert(kTitlePlayers >= 2 && kTitlePlayers <= kMaxPlayers, "the ceiling of a title fits in the tables");\n', ''),
    ('eight: the ceiling in LobbyConfig is four bytes', 'Includes/azl/dlp_lobby.hpp', '    u8 max_players;   // the ceiling of the title', '    u32 max_players;   // the ceiling of the title'),
    ('eight: every lobby has the ceiling of the tables whatever its title says', 'Includes/azl/dlp_lobby.hpp', 'flags2_ = static_cast<u8>(TitlePlayers(cfg.max_players) << kF2CapShift);', 'flags2_ = static_cast<u8>(kMaxPlayers << kF2CapShift);'),
    ('eight: the 0 of a configuration reaches the lobby as it is', 'Includes/azl/dlp_lobby.hpp', 'flags2_ = static_cast<u8>(TitlePlayers(cfg.max_players) << kF2CapShift);', 'flags2_ = static_cast<u8>(cfg.max_players << kF2CapShift);'),
    ('eight: the lobby names the default ceiling by itself', 'Includes/azl/dlp_lobby.hpp', 'flags2_ = static_cast<u8>(TitlePlayers(cfg.max_players) << kF2CapShift);', 'flags2_ = static_cast<u8>((cfg.max_players == 0 ? kTitlePlayers : cfg.max_players) << kF2CapShift);'),
    ('eight: the ceiling of the title is never read', 'Includes/azl/dlp_lobby.hpp', '        return static_cast<u32>(flags2_ >> kF2CapShift);', '        return kMaxPlayers;'),
    ('eight: the ceiling shares its bits with the flags', 'Includes/azl/dlp_lobby.hpp', 'static constexpr u8 kF2CapShift = 4; ', 'static constexpr u8 kF2CapShift = 2; '),
    ('eight: the assertion of the shared byte is gone', 'Includes/azl/dlp_lobby.hpp', '    static_assert((kMaxPlayers << kF2CapShift) <= 0xFF && (kF2FinalRoster | kF2External | kF2OnNet | kF2Stalled) < (1u << kF2CapShift),\n                  "the ceiling of the title and the three bits share one byte");\n', ''),
    ('eight: the teardown of the searcher clears the ceiling of the title', 'Includes/azl/dlp_lobby.hpp', 'flags2_ = static_cast<u8>(flags2_ & ~kF2FinalRoster);  // (only that bit:', 'flags2_ = 0;  // (only that bit:'),
    ('eight: the last look at the roster clears the ceiling of the title', 'Includes/azl/dlp_lobby.hpp', '            flags2_ = static_cast<u8>(flags2_ & ~kF2FinalRoster);\n            ReadRoster();', '            flags2_ = 0;\n            ReadRoster();'),
    ('eight: the mode bits are set over the ceiling of the title', 'Includes/azl/dlp_lobby.hpp', 'flags2_ = static_cast<u8>(on ? (flags2_ | bit) : (flags2_ & ~bit));', 'flags2_ = static_cast<u8>(on ? bit : 0);'),
    ('eight: a stray write of the byte that holds the ceiling', 'Includes/azl/dlp_lobby.hpp', '        cli_state_ = kCliIdle;\n        cursor_ = 0;\n        filter_ = 0;\n', '        cli_state_ = kCliIdle;\n        cursor_ = 0;\n        filter_ = 0;\n        flags2_ = 0;\n'),
    ('eight: the ceiling of the title is not applied to the clients a game asks for', 'Includes/azl/dlp_lobby.hpp', 'const u32 most = CeilingClients();', 'const u32 most = kMaxClients;'),
    ('eight: the clients a game asks for are cut to the capacity of the tables', 'Includes/azl/dlp_lobby.hpp', '        const u32 most = CeilingClients();  // (1..3 for a title of four players, 1..7 for one of eight)\n        max_clients_ = static_cast<u8>(max_clients < 1 ? 1 : (max_clients > most ? most : max_clients));', '        max_clients_ = static_cast<u8>(max_clients < 1 ? 1 : (max_clients > kMaxClients ? kMaxClients : max_clients));'),
    ('eight: the clients a game asks for are not cut', 'Includes/azl/dlp_lobby.hpp', 'max_clients_ = static_cast<u8>(max_clients < 1 ? 1 : (max_clients > most ? most : max_clients));', 'max_clients_ = static_cast<u8>(max_clients < 1 ? 1 : max_clients);'),
    ('eight: a searcher of a title of four lists a lobby of eight', 'Includes/azl/dlp_lobby.hpp', 'a.max_nodes > Ceiling() || hg.total_nodes < 1', 'a.max_nodes > kMaxPlayers || hg.total_nodes < 1'),
    ('eight: a searcher lists a lobby of any size', 'Includes/azl/dlp_lobby.hpp', 'if (a.max_nodes < 2 || a.max_nodes > Ceiling() || hg.total_nodes < 1', 'if (a.max_nodes < 2 || hg.total_nodes < 1'),
    ('eight: the entry of a session that was not in the table says the capacity of the tables', 'Includes/azl/dlp_lobby.hpp', 'g->max_nodes = static_cast<u8>(Ceiling());', 'g->max_nodes = kMaxPlayers;'),
    ('eight: the lobby reads every member the tables hold whatever its title', 'Includes/azl/dlp_lobby.hpp', 'return n > Ceiling() ? Ceiling() : n;', 'return n > kMaxPlayers ? kMaxPlayers : n;'),
    ('eight: the creator of a title of four has a slot for every node of the tables', 'Includes/azl/dlp_lobby.hpp', 'DLP_NOINLINE void TrackClients(const u8* nodes, u32 n, u32 now) {\n        for (u32 s = 0; s < CeilingClients(); ++s) {', 'DLP_NOINLINE void TrackClients(const u8* nodes, u32 n, u32 now) {\n        for (u32 s = 0; s < kMaxClients; ++s) {'),
    ('eight: only an id above the tables is ejected with the shared timer', 'Includes/azl/dlp_lobby.hpp', 'if (nodes[i] > Ceiling() && Elapsed(now, aux_ms_) >= kResendMs) {', 'if (nodes[i] > kMaxPlayers && Elapsed(now, aux_ms_) >= kResendMs) {'),
    ('eight: an id above the ceiling of the title is never ejected', 'Includes/azl/dlp_lobby.hpp', '            if (nodes[i] > Ceiling() && Elapsed(now, aux_ms_) >= kResendMs) {\n                net_->Kick(nodes[i]);\n                aux_ms_ = now;\n            }\n', ''),
    ('eight: a sixth use of the ceiling of the title that no pin names', 'Includes/azl/dlp_lobby.hpp', '            while (cursor_ < kMaxGroups) {', '            while (cursor_ < kMaxGroups && cursor_ < Ceiling()) {'),
    ('eight: one more loop over every slot of the creator', 'Includes/azl/dlp_lobby.hpp', APPEND, '\n// for (u32 s = 0; s < kMaxClients; ++s) {\n'),
    ('eight: the ceiling of the title cannot be read from outside', 'Includes/azl/dlp_lobby.hpp', '    u32 max_players() const {\n        return Ceiling();\n    }\n', ''),
    ('eight: the probe has no wrapper for max_players', 'Tests/dlp_stack_probe.cpp', 'PROBE_NOINLINE u32 p_max_players(const DlpLobby* l) { return l->max_players(); }\n', ''),
    ('eight: the node ids of GetConnectingNodes are u16 in its frame again', 'Includes/azl/dlp_ipc.hpp', 'u8 ids[kMaxPlayers];', 'u16 ids[kMaxPlayers];'),
    ('eight: the client ids of GetConnectingClients are u16 in its frame again', 'Includes/azl/dlp_ipc.hpp', 'u8 ids[kMaxClients];', 'u16 ids[kMaxClients];'),
    ('eight: a third vector of u16 ids in a handler', 'Includes/azl/dlp_ipc.hpp', APPEND, '\n// u16 ids[2];\n'),
    ('eight: the lobby gives the node ids as u16', 'Includes/azl/dlp_lobby.hpp', 'u32 ClientConnectingNodes(u8* ids, u32 capacity, u32* total) const {', 'u32 ClientConnectingNodes(u16* ids, u32 capacity, u32* total) const {'),
    ('eight: the lobby gives the client ids as u16', 'Includes/azl/dlp_lobby.hpp', 'u32 ServerConnectingClients(u8* ids, u32 capacity, u32* total) const {', 'u32 ServerConnectingClients(u16* ids, u32 capacity, u32* total) const {'),
