    ('island test: the nodes of the network the console hosts are not read', 'Tests/dlp_real_island_test.cpp', '    CHECK_EQ(h.e().GetConnectionStatus().max_nodes, 4u);  // "hosting network (max 4 nodes ...)", as the capture\'s beacon says\n', ''),
    ('island test: H does not hold what the game lists while the clients come in', 'Tests/dlp_real_island_test.cpp', '            CHECK(Frames(g, seen, 3000, [&](const std::string& line) { return line == want; }));\n', ''),
    ('island test: H does not count the frames to the clients that wait', 'Tests/dlp_real_island_test.cpp', '            CHECK_EQ(said, 0u);  // (as in the capture: nothing on channel 2 while the clients wait - and no announcement of ours, nobody is looking)\n', ''),
    ('island test: H does not count the AcceptClient of the confirmation', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(g.calls(0x09), kIslandClients);  // H: three AcceptClient ...\n', ''),
    ('island test: H does not count the StartDistribution of the confirmation', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(g.calls(0x07), 1u);              // H: ... and ONE StartDistribution, before the game read anything again\n', ''),
    ('island test: H does not hold state 8 with the three clients', 'Tests/dlp_real_island_test.cpp', '        CHECK(seen.Has("state 8, 3 clients: 2=07 3=07 4=07"));\n', ''),
    ('island test: H lets state 8 come at the grace', 'Tests/dlp_real_island_test.cpp', "        CHECK(to8 < DlpLobby::kStartGraceMs);  // (every client answered: nobody was thrown out at the lobby's grace)\n", ''),
    ('island test: H does not count the passphrase', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(g.calls(0x08), 1u);  // H: the passphrase was given ONCE\n', ''),
    ('island test: H does not hold state 9 with no client', 'Tests/dlp_real_island_test.cpp', '        CHECK(seen.Has("state 9, 0 clients:"));  // at 9 the game waits for GetConnectingClients = 0: it is 0 at the first read\n', ''),
    ('island test: H does not read the passphrase the clients got', 'Tests/dlp_real_island_test.cpp', '            CHECK(pass.size() == 9 && std::memcmp(pass.data(), kDlpRealIslandPass, 9) == 0);\n', ''),
    ('island test: H does not count the fragments the clients got', 'Tests/dlp_real_island_test.cpp', '            CHECK_EQ(m->received(4, 0) + m->received(4, 1), 0u);  // nothing of the child was sent\n', ''),
    ('island test: H does not hold the sequence of the packets of the host', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(d.p[0x0D], want_seq);\n', ''),
    ('island test: H does not compare the packets of the host with the capture', 'Tests/dlp_real_island_test.cpp', '        CHECK(Same(p, g, kDlpRealIslandSeed));\n', ''),
    ('island test: H lets the host start before the game accepted', 'Tests/dlp_real_island_test.cpp', "        CHECK_EQ(w.early, 0u);          // before the game accepted: the Auth and nothing else (ours sends it at the admission, Azahar's host at the accept)\n", ''),
    ('island test: H does not count the StartDistribution packets', 'Tests/dlp_real_island_test.cpp', '                CHECK_EQ(w.a3_to[s], 1u);  // ONE StartDistribution to each\n', ''),
    ('island test: H does not count the finals', 'Tests/dlp_real_island_test.cpp', '                CHECK_EQ(w.a7_to[s], 1u);  // ONE final to each\n', ''),
    ('island test: H does not count the fragments on the wire', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(w.content, 0u);  // H: not one fragment of the child on the wire\n', ''),
    ('island test: H does not compare the address of the two networks', 'Tests/dlp_real_island_test.cpp', "            CHECK(found.host_mac_address == h.mac());  // the address announced in the Download Play is the BSSID of the game's network\n", ''),
    ('island test: H does not hold the transmitter of the beacons', 'Tests/dlp_real_island_test.cpp', '            CHECK(o.from == h.mac());\n', ''),
    ('island test: H does not hold that the players come back', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(mask, (1u << players) - 1u);  // every player the game counted is in its network\n', ''),
    ('island test: H does not check the rules of Azahar', 'Tests/dlp_real_island_test.cpp', "    CHECK_RULES();  // no frame of the room broke a rule of Azahar's (Tests/azahar_rules.hpp)\n", ''),
    ('island test: in C nobody asks for the content', 'Tests/dlp_real_island_test.cpp', '    cl[asks]->want_content = true;\n', ''),
    ('island test: C does not count the request of content', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(h.real.counters().content, 1u);\n', ''),
    ('island test: C does not hold what the game lists at state 8', 'Tests/dlp_real_island_test.cpp', '        CHECK(seen.Has(alone ? "state 8, 0 clients:" : "state 8, 2 clients: 2=07 4=07"));\n', ''),
    ('island test: C does not ask the game for the client that asked', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(g.ClientInfo(asked_node).res(), R_NO_DATA);\n', ''),
    ('island test: C does not count the passphrase', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(g.calls(0x08), 1u);  // C: the passphrase was given ONCE\n', ''),
    ('island test: C does not hold state 9', 'Tests/dlp_real_island_test.cpp', '        CHECK(seen.Has("state 9, 0 clients:"));  // C: the game reads 9 with nobody left to wait for, as if every player had the passphrase\n', ''),
    ('island test: C does not hold that the client that asked has no passphrase', 'Tests/dlp_real_island_test.cpp', '        CHECK(cl[asks]->passphrase().empty());                                   // the client that asked never gets the passphrase\n', ''),
    ('island test: C does not count the fragments the client that asked got', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(cl[asks]->received(4, 0) + cl[asks]->received(4, 1), 0u);       // ... and not one fragment of the child\n', ''),
    ('island test: C does not count the clients with the passphrase', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(with_pass, n - 1);\n', ''),
    ('island test: C does not count the fragments on the wire', 'Tests/dlp_real_island_test.cpp', '        CHECK_EQ(w.content, 0u);  // C: not one fragment of the child on the wire, though a client asked for it\n', ''),
    ('island test: H lets a packet the capture does not have pass', 'Tests/dlp_real_island_test.cpp', '            std::printf("   a packet of the host that the capture does not have: %s\\n", Hex(d.p.data(), d.p.size()).c_str());\n            CHECK(false);\n', '            std::printf("   a packet of the host that the capture does not have: %s\\n", Hex(d.p.data(), d.p.size()).c_str());\n'),
    ('island golden: the script that makes the golden data of Mario Party: Island Tour is gone', 'Tests/make_dlp_real_island_goldens.py', GONE, None),
    ('island golden: the file is not marked as generated', 'Tests/dlp_real_island_golden.inc', '// Generated by Tests/make_dlp_real_island_goldens.py from the capture of 2026-11-13', '// Written from the capture of 2026-11-13'),
    ('island golden: a byte of the capture edited by hand', 'Tests/dlp_real_island_golden.inc', '    {"A1", "402.106", 2, 1, 2, 20, kDlpRealIsland_05_A1, 0xf9f4edd2,', '    {"A1", "402.106", 2, 1, 2, 20, kDlpRealIsland_05_A1, 0xf9f4edd3,'),
    ('island golden: another seed', 'Tests/dlp_real_island_golden.inc', 'static const std::uint8_t kDlpRealIslandSeed[4] = {0xb8, 0xf4, 0x6b, 0xff};\n', 'static const std::uint8_t kDlpRealIslandSeed[4] = {0x38, 0x74, 0x6b, 0x7f};\n'),
    ('island golden: the host of the capture announces another child', 'Tests/dlp_real_island_golden.inc', 'static const std::uint64_t kDlpRealIslandChild = 0x00040001000f8200ULL;  // frame 0, +0x10\n', 'static const std::uint64_t kDlpRealIslandChild = 0x00040001000f8100ULL;  // frame 0, +0x10\n'),
    ('island golden: the host of the capture announces two nodes', 'Tests/dlp_real_island_golden.inc', 'static const unsigned kDlpRealIslandMaxNodes = 4;  // frame 0, +0x20\n', 'static const unsigned kDlpRealIslandMaxNodes = 2;  // frame 0, +0x20\n'),
    ('island golden: another passphrase in the place of the stand-in', 'Tests/dlp_real_island_golden.inc', 'static const std::uint8_t kDlpRealIslandPass[9] = {0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x76, 0x00};  // the final, +0x14: the STAND-IN "1234567v" (seven hex digits and a \'v\', as the game makes it)\n', 'static const std::uint8_t kDlpRealIslandPass[9] = {0x39, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x76, 0x00};  // the final, +0x14: the STAND-IN "1234567v" (seven hex digits and a \'v\', as the game makes it)\n'),
    ('island golden: frame 0 carries the bytes of the title', 'Tests/dlp_real_island_golden.inc', '    {"F0", "285.079", 1, 1, 65535, 768, kDlpRealIsland_00_F0, 0x6afc8d60, 0x7f7f7f35, {0x40, 0x2f8}},\n', '    {"F0", "285.079", 1, 1, 65535, 768, kDlpRealIsland_00_F0, 0x6afc8d60, 0x7f7f7f35, {0x0, 0x0}},\n'),
    ('island golden: the dialogue without its last packet', 'Tests/dlp_real_island_golden.inc', 'static const DlpRealGolden kDlpRealIslandDialog[9] = {\n', 'static const DlpRealGolden kDlpRealIslandDialog[8] = {\n'),
    ('island golden: the script has an empty stand-in', 'Tests/make_dlp_real_island_goldens.py', "STAND_IN = b'1234567v\\x00'    # what replaces the passphrase of the final (+0x14, nine bytes)\n", "STAND_IN = b''    # what replaces the passphrase of the final (+0x14, nine bytes)\n"),
    ('island golden: the script leaves the passphrase of the capture in the final', 'Tests/make_dlp_real_island_goldens.py', '            g = sealed(seed, g[:0x14] + STAND_IN + g[0x1D:])\n', ''),
    ('island golden: the script does not look for the passphrases of the capture in what it writes', 'Tests/make_dlp_real_island_goldens.py', "    refuse(any(p[:8] in g for pid, r, g, red in packets for p in passphrases), 'a passphrase of the capture in a packet')\n", ''),
    ('island golden: the script leaves the title in frame 0', 'Tests/make_dlp_real_island_goldens.py', '            red = [(0x40, 0x2F8)]\n', '            red = []\n'),
    ('island golden: the script leaves the icon in frames 1-3', 'Tests/make_dlp_real_island_goldens.py', '            red = [(0x10, len(b))]\n', '            red = [(0x10, 0x14)]\n'),
    ('island golden: the script takes the addresses of the capture as text', 'Tests/make_dlp_real_island_goldens.py', "    macs = [bytes.fromhex(tx[:17].replace(':', '')) for tx in (host_tx, client_tx)]\n", '    macs = [tx[:17].encode() for tx in (host_tx, client_tx)]\n'),
    ('island golden: the script goes on without the addresses and the names of the two nodes', 'Tests/make_dlp_real_island_goldens.py', "    refuse(not all(nicks) or any(len(mac) != 6 for mac in macs) or macs[0] == macs[1], 'the two nodes of the capture are not read')\n", ''),
    ('island golden: the script does not look for the addresses of the capture in the bytes it writes', 'Tests/make_dlp_real_island_goldens.py', "    refuse(any(mac in p[2] or mac[::-1] in p[2] for mac in macs for p in packets), 'an address of a node of the capture in a packet')\n", ''),
    ('island golden: the script does not look for the names of the capture in the bytes it writes', 'Tests/make_dlp_real_island_goldens.py', "    refuse(any(n.encode(enc) in p[2] for n in nicks for enc in ('utf-8', 'utf-16-be', 'utf-16-le') for p in packets), 'a name of a node of the capture in a packet')\n", ''),
    ('island golden: the script does not look for the addresses and the names of the capture in the text it writes', 'Tests/make_dlp_real_island_goldens.py', '    refuse(any(bad in text.lower() for bad in [tx[:17].lower() for tx in (host_tx, client_tx)] + [mac.hex() for mac in macs] + [n.lower() for n in nicks]),\n', ''),
    ('island golden: the refusal of the script returns at once', 'Tests/make_dlp_real_island_goldens.py', 'def refuse(found, what):\n', 'def refuse(found, what):\n    return\n'),
    ('island golden: the refusal of the script only prints', 'Tests/make_dlp_real_island_goldens.py', "        raise SystemExit('REFUSED, nothing written: ' + what)\n", "        print('REFUSED, nothing written: ' + what)\n"),
    ('island golden: the refusal of the script is an assert again', 'Tests/make_dlp_real_island_goldens.py', "    if found:\n        raise SystemExit('REFUSED, nothing written: ' + what)\n", '    assert not found, what\n'),
    ('island golden: the script writes the file before it looks for the addresses', 'Tests/make_dlp_real_island_goldens.py', "    refuse(any(mac in p[2] or mac[::-1] in p[2] for mac in macs for p in packets), 'an address of a node of the capture in a packet')\n", "    open(dest, 'w', newline='\\n').write(text)\n    refuse(any(mac in p[2] or mac[::-1] in p[2] for mac in macs for p in packets), 'an address of a node of the capture in a packet')\n"),
