def mutate(base, rel, old, new):
    """applies ONE mutant to the tree at base: (None, undo), where undo() gives the tree back as it was, or (the reason, None) when the
    mutant does not apply (its pattern is not found once: counted as not caught, and the others still run)"""
    p = os.path.normpath(os.path.join(base, rel))
    made = []
    saved = None
    if os.path.exists(p):
        saved = open(p, 'rb').read()
    else:  # a file that must not exist (dist/default.3gx): the mutant makes it
        d = os.path.dirname(p)
        while not os.path.isdir(d):
            made.append(d)
            d = os.path.dirname(d)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, 'wb').write(b'')

    def undo():
        if saved is None:
            if os.path.exists(p):
                os.remove(p)
            for d in made:
                if os.path.isdir(d) and not os.listdir(d):
                    os.rmdir(d)
        else:
            open(p, 'wb').write(saved)
    if old is BYTE:
        data = bytearray(open(p, 'rb').read())
        data[new[0]] = new[1]
        open(p, 'wb').write(bytes(data))
    elif old is FUNC:
        changed = new(open(p, 'rb').read())   # (read first: opening for writing empties the file)
        open(p, 'wb').write(changed)
    elif old is GONE:
        os.remove(p)
    else:
        raw = open(p, 'rb').read().decode('utf-8')
        crlf = '\r\n' in raw
        s = raw.replace('\r\n', '\n')
        if old is APPEND:
            s = s + new
        else:
            n = s.count(old)
            if n != 1:
                undo()
                return 'pattern found %d times, not once' % n, None
            s = s.replace(old, new)
        open(p, 'wb').write((s.replace('\n', '\r\n') if crlf else s).encode('utf-8'))
    return None, undo


def dry_one(entry):
    """MUTANT_DRYRUN: whether the mutant still applies to the tree as it is now (read only: nothing is copied, the check does not run)"""
    name, rel, old, new = entry[:4]
    if not rel:
        return True, 'OK   ' + name
    p = os.path.normpath(os.path.join(root, rel))
    there = os.path.exists(p)
    why = None
    if old is BYTE:
        if not there or new[0] >= os.path.getsize(p) or open(p, 'rb').read()[new[0]] == new[1]:
            why = 'the byte is not there or does not change'
    elif old is FUNC:
        if there:
            b = open(p, 'rb').read()
            if new(b) == b:
                why = 'the function leaves the file as it is'
    elif old is GONE:
        if not there:
            why = 'the file to delete is not there'
    elif old is not APPEND:
        if not there:
            why = 'the file is not there'
        else:
            s = open(p, 'rb').read().decode('utf-8').replace('\r\n', '\n')
            n = s.count(old)
            if n != 1:
                why = 'pattern found %d times, not once' % n
            elif old == new:
                why = 'the new text is the old one'
    return why is None, ('OK   ' if why is None else 'BAD  ') + name + ('' if why is None else ' -> ' + why)


# MUTANT_OLD=1 is the runner as it was before 2026-11-15 (a fresh copy of the tree for every mutant, the whole check run on it), kept to
# compare the verdicts. Otherwise every worker keeps ONE tree, puts each mutant in it and takes it out again, and the check stops at its
# first failure on a mutant (POLICY_FAIL_FAST: the unchanged copy passes every pin, so the first failure is the mutant's; the unchanged
# copy itself runs the whole check). At the end the unchanged copy runs again on every tree kept, and it must still pass.
OLD = bool(os.environ.get('MUTANT_OLD'))
_local = threading.local()
_trees = []
_trees_lock = threading.Lock()


def check(base, fail_fast):
    env = dict(os.environ)
    env.pop('POLICY_FAIL_FAST', None)
    if fail_fast:
        env['POLICY_FAIL_FAST'] = '1'
    return subprocess.run(['bash', 'Tests/policy_check.sh'], cwd=base, capture_output=True, text=True, env=env)


def run_one(entry):
    name, rel, old, new = entry[:4]
    want_fail = entry[4] if len(entry) > 4 else name != 'unchanged'
    if OLD:
        tmp, base = make_tree()
    else:
        base = getattr(_local, 'base', None)
        if base is None:
            tmp, base = make_tree()
            _local.base = base
            with _trees_lock:
                _trees.append((tmp, base))
    undo = None
    try:
        if rel:
            why, undo = mutate(base, rel, old, new)
            if why:
                return False, 'BAD  ' + name + ' -> ' + why
        r = check(base, fail_fast=not OLD and name != 'unchanged')
        ok = (r.returncode != 0) == want_fail
        first = (r.stdout.strip().splitlines() or [''])[0][:150]
        return ok, ('OK   ' if ok else 'BAD  ') + name + ' -> exit ' + str(r.returncode) + ' | ' + first
    finally:
        if undo:
            undo()
        if OLD:
            shutil.rmtree(tmp, ignore_errors=True)


# Each mutant runs in a private tree, so they run side by side (the checks are bash processes: the time is theirs).
failed = 0
if os.environ.get('MUTANT_FILTER'):
    import re
    wanted = re.compile(os.environ['MUTANT_FILTER'])
    mutants = [m for m in mutants if m[0] == 'unchanged' or wanted.search(m[0])]
if os.environ.get('MUTANT_FILES'):  # a regular expression on the mutant's FILE (the names do not say it): the mutants of the files a piece touches
    import re
    wanted_files = re.compile(os.environ['MUTANT_FILES'])
    mutants = [m for m in mutants if m[0] == 'unchanged' or (m[1] and wanted_files.search(m[1]))]
if os.environ.get('MUTANT_FROM'):
    first = int(os.environ['MUTANT_FROM'])
    mutants = [m for i, m in enumerate(mutants) if i == 0 or i >= first]
if os.environ.get('MUTANT_DRYRUN'):
    for ok, line in map(dry_one, mutants):
        if not ok:
            print(line, flush=True)
        failed += 0 if ok else 1
    print('dry run: %d mutants that do not apply to this tree (of %d, the unchanged copy included); the check was not run' % (failed, len(mutants)))
    sys.exit(1 if failed else 0)
try:
    with concurrent.futures.ThreadPoolExecutor(max_workers=int(os.environ.get('MUTANT_JOBS', '8'))) as pool:
        for ok, line in pool.map(run_one, mutants):
            print(line, flush=True)
            failed += 0 if ok else 1
    with concurrent.futures.ThreadPoolExecutor(max_workers=max(1, len(_trees))) as pool:  # (a mutant taken out badly, or a check that wrote in its tree, fails here)
        again = list(pool.map(lambda t: check(t[1], fail_fast=False), _trees))
    for r in again:
        if r.returncode != 0:
            failed += 1
            print('BAD  a tree kept by a worker is no longer the unchanged one -> exit %d | %s' % (r.returncode, (r.stdout.strip().splitlines() or [''])[0][:150]), flush=True)
    if _trees:
        print('the %d trees kept by the workers still pass as the unchanged copy' % len(_trees))
finally:
    for tmp, base in _trees:
        shutil.rmtree(tmp, ignore_errors=True)
print('%d mutants not caught (of %d, the unchanged copy included)' % (failed, len(mutants)))
sys.exit(1 if failed else 0)
